import os
import torch


class Config:
    # ==========================
    # General Settings
    # ==========================
    SEED = 42
    EXP_NAME = "idea_6"
    DEBUG = False  # Set to True to run on a small subset for debugging
    DEBUG_SUBSET_SIZE = 100

    # ==========================
    # Directories & Paths
    # ==========================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the provided script
    TRAIN_META = os.path.join(METADATA_DIR, "train.csv")
    VAL_META = os.path.join(METADATA_DIR, "val.csv")
    TEST_META = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for this specific experiment
    WORKING_DIR = os.path.join("./working", EXP_NAME)

    # Cache directory (reusing working dir for simplicity)
    CACHE_DIR = WORKING_DIR

    # Final submission path
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Model Checkpoint path
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # ==========================
    # Model Architecture
    # ==========================
    # Using EfficientNetV2-Small as per strategy
    MODEL_NAME = "tf_efficientnetv2_s"

    # Ordinal Regression: 5 classes (0-4) require 4 binary output units
    # Targets: 0->[0000], 1->[1000], 2->[1100], 3->[1110], 4->[1111]
    NUM_CLASSES = 5
    NUM_OUTPUTS = 4

    PRETRAINED = True
    DROP_RATE = 0.2  # Dropout rate before the final linear layer

    # ==========================
    # Data Processing
    # ==========================
    IMG_SIZE = 384
    RESIZE_STRATEGY = "squash"  # Resize directly ignoring aspect ratio

    # ==========================
    # Augmentation (Photometric)
    # ==========================
    # Parameters to address domain shift
    AUG_BRIGHTNESS = 0.2
    AUG_CONTRAST = 0.2
    AUG_HUE = 0.1
    AUG_SATURATION = 0.1
    AUG_PROB = 0.75  # Probability of applying augmentations

    # ==========================
    # Training Hyperparameters
    # ==========================
    BATCH_SIZE = 32
    EPOCHS = 15

    # Optimization
    LEARNING_RATE = 3e-4
    WEIGHT_DECAY = 1e-2  # For AdamW

    # Scheduler (Cosine Annealing)
    T_MAX = EPOCHS
    MIN_LR = 1e-6

    # Early Stopping
    PATIENCE = 4

    # ==========================
    # Hardware
    # ==========================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4  # Safe value for 12 vCPUs

    @classmethod
    def setup(cls):
        """
        Creates necessary directories for the experiment.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Set reproducible seeds
        import random
        import numpy as np

        random.seed(cls.SEED)
        np.random.seed(cls.SEED)
        torch.manual_seed(cls.SEED)
        if torch.cuda.is_available():
            torch.cuda.manual_seed_all(cls.SEED)
            torch.backends.cudnn.deterministic = True
            torch.backends.cudnn.benchmark = False
